def outer():
    value='old'
    def change():
        class C:
            nonlocal value
            value='new'
    yield change
    try:print(value)
    except UnboundLocalError:print('unbound')
generator=outer()
next(generator)()
try:next(generator)
except StopIteration:pass

def outer():
    value='old'
    def change():
        class C:
            nonlocal value
            del value
    yield change
    try:print(value)
    except UnboundLocalError:print('unbound')
generator=outer()
next(generator)()
try:next(generator)
except StopIteration:pass
